TENS = ["", "on", "yirmi", "otuz", "kırk", "elli", "altmış", "yetmiş", "seksen", "doksan"]
DIG = ["sıfır", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"]
AYLAR = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"]
def tr3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(("" if h == 1 else ONES[h] + " ") + "yüz")
    if t:
        s.append(TENS[t])
    if o:
        s.append(ONES[o])
    return " ".join(s)
def trnum(n):
    n = int(n)
    if n == 0:
        return "sıfır"
    parts = []
    for val, word in ((10**9, "milyar"), (10**6, "milyon"), (1000, "bin")):
        q, n = divmod(n, val)
        if q:
            parts.append("bin" if (val == 1000 and q == 1) else tr3(q) + " " + word)
    if n:
        parts.append(tr3(n))
    return " ".join(parts)
SUB = {"TL": ("lira", "kuruş", "Türk Lirası"), "USD": ("dolar", "sent", "Dolar"), "EUR": ("euro", "sent", "Euro"), "GBP": ("sterlin", "peni", "İngiliz Sterlini")}
def amt(x, cur):
    x = abs(float(x))
    cents = int(round(x * 100))
    whole, frac = divmod(cents, 100)
    major, minor, full = SUB[cur]
    if frac == 0:
        return trnum(whole) + " " + full
    return trnum(whole) + " " + major + " " + trnum(frac) + " " + minor
def suffix(text):
    w = text.strip().split(" ")[-1].lower()
    vow = [c for c in w if c in "aeıioöuü"]
    v = vow[-1] if vow else "e"
    hard = w[-1:] in list("çfhkpsşt")
    d = "t" if hard else "d"
    return "'" + d + {"a": "ır", "ı": "ır", "e": "ir", "i": "ir", "o": "ur", "u": "ur", "ö": "ür", "ü": "ür"}[v]
def pdate(s):
    try:
        d, m, y = str(s).strip().split(".")
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(d):
    return "%d %s %d" % (d.day, AYLAR[d.month - 1], d.year)
def digits_tr(s):
    return " ".join(DIG[int(c)] for c in str(s) if c.isdigit())
def jload(v, default):
    try:
        x = json.loads(v) if isinstance(v, str) else v
        return x if x is not None else default
    except Exception:
        return default
