def tr3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(("" if h == 1 else ONES[h] + " ") + "yüz")
    if t:
        s.append(TENS[t])
    if o:
